"use strict";

const { REST, Routes } = require("discord.js");
const { commands } = require("./hello_bot.js");

async function main() {
  const token = process.env.DISCORD_TOKEN;
  const clientId = process.env.DISCORD_CLIENT_ID;
  const guildId = process.env.DISCORD_GUILD_ID;
  if (!token || !clientId) {
    throw new Error("set DISCORD_TOKEN and DISCORD_CLIENT_ID");
  }
  const body = commands.map((command) => command.data.toJSON());
  const rest = new REST({ version: "10" }).setToken(token);
  if (guildId) {
    await rest.put(Routes.applicationGuildCommands(clientId, guildId), { body });
    console.log(`Registered ${body.length} command(s) in guild ${guildId}.`);
  } else {
    await rest.put(Routes.applicationCommands(clientId), { body });
    console.log(`Registered ${body.length} command(s) globally.`);
  }
}


main().catch((e) => {
  console.error(e);
  process.exit(1);
});
